    def pos(obj, default=None):
        if is_seq(obj) and len(obj) >= 2:
            return obj[0], obj[1]
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("col", "row")):
                if kx in obj and ky in obj:
                    return obj.get(kx), obj.get(ky)
        return default

    def move_towards(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_list(keys):
        if not isinstance(observation, dict):
            return []
        for k in keys:
            v = observation.get(k, [])
            if v:
