        if not pts:
            return None
        if mode == "max":
            return max(pts, key=lambda c: manhattan(start, c))
        return min(pts, key=lambda c: manhattan(start, c))

    if not isinstance(observation, dict):
        return [0, 0]

    sx, sy = pos(observation.get("self_position", observation.get("position", (0, 0))), (0, 0))
    ox, oy = pos(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))), (sx, sy))
